const root=document.querySelector('#trade-center-workspace');let teams=[],a='',b='',sendA=new Set(),sendB=new Set(),context={projections:{},games:{},injuries:{},slots:[]},suggestions=[],filters={a:{query:'',position:'ALL'},b:{query:'',position:'ALL'}},generation=0;
