function render(recompute=true){if(teams.length<2)return;const options=selected=>teams.map(t=>`<option value="${t.rosterId}" data-avatar="${esc(t.avatar||'')}" ${String(t.rosterId)===selected?'selected':''}>${esc(t.team)} · ${esc(t.manager)}</option>`).join('');root.innerHTML=`<div class="tl-topbar"><span>${context.week?'WEEK '+context.week+' · '+context.season:'WEEKLY PROJECTIONS UNAVAILABLE'}</span><button class="button button--ghost" id="tl-refresh">Refresh data</button></div><p id="tl-share-notice" class="notice" ${shareNotice?'':'hidden'}>${esc(shareNotice)}</p><section id="tl-upgrades" aria-live="polite"></section><div id="tl-partners"></div><div class="tc-controls"><label>Your franchise<select id="tc-a">${options(a)}</select></label><label>Trade partner<select id="tc-b">${options(b)}</select></label></div><div class="tl-planning">${[a,b].map(id=>`<label>${esc(team(id).manager)} strategy<select data-plan="${id}">${['Balanced','Contend','Rebuild'].map(g=>`<option ${plan(id)===g?'selected':''}>${g}</option>`).join('')}</select></label>`).join('')}</div><div id="tl-needs"></div><div class="tl-offer-launch"><div><p class="kicker">FIND YOUR NEXT DEAL</p><h3>Buy a target. Or shop your player.</h3><p>Right list: who you want. Left list: who you’ll trade. Use ◇ to protect assets.</p></div><div class="tl-builder-buttons"><button class="button button--primary" id="tl-build-offer">Build offers</button><button class="button button--ghost" id="tl-shop">Shop my players</button></div></div><div id="tl-offers" aria-live="polite"></div><div id="tl-saved"></div><div id="tl-compare"></div><div class="tl-pickers">${['a','b'].map(side=>{const t=team(side==='a'?a:b),f=filters[side];return `<section><header>${logo(t)}<div><h3>${esc(t.team)}</h3><small>Select players or picks</small></div></header><div class="tl-filters"><input type="search" data-search="${side}" placeholder="Search players or picks" aria-label="Search ${esc(t.team)} players" value="${esc(f.query)}"><select data-position="${side}" aria-label="Filter ${esc(t.team)} by position">${['ALL','QB','RB','WR','TE','PICKS'].map(p=>`<option ${f.position===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="tl-pick-list" id="tl-list-${side}">${pickers(side)}</div></section>`;}).join('')}</div><div id="tl-deal" class="tl-deal"></div><div class="tc-actions"><button class="button button--primary" id="tc-simulate">Analyze both sides</button><button class="button button--ghost" id="tc-reset">Clear deal</button><span id="tl-count"></span></div><div id="tc-output" aria-live="polite"></div>`;
 root.querySelector('#tc-a').addEventListener('change',e=>{a=e.target.value;if(a===b)b=String(teams.find(t=>String(t.rosterId)!==a).rosterId);sendA.clear();sendB.clear();pickA.clear();pickB.clear();render();});root.querySelector('#tc-b').addEventListener('change',e=>{b=e.target.value;if(a===b)a=String(teams.find(t=>String(t.rosterId)!==b).rosterId);sendA.clear();sendB.clear();pickA.clear();pickB.clear();render();});
 for(const side of ['a','b']){bindPicks(side);const update=()=>{root.querySelector(`#tl-list-${side}`).innerHTML=pickers(side);bindPicks(side);images();};root.querySelector(`[data-search="${side}"]`).addEventListener('input',e=>{filters[side].query=e.target.value;update();});root.querySelector(`[data-position="${side}"]`).addEventListener('change',e=>{filters[side].position=e.target.value;update();});}
 root.querySelectorAll('[data-plan]').forEach(select=>select.addEventListener('change',()=>{plans[select.dataset.plan]=select.value;try{localStorage.setItem('dcc-trade-plans',JSON.stringify(plans));}catch{}stopShopping();root.querySelector('#tl-offers').replaceChildren();}));renderPlanning();root.querySelector('#tl-shop').addEventListener('click',shopPlayers);root.querySelector('#tl-build-offer').addEventListener('click',generateOffers);root.querySelector('#tc-simulate').addEventListener('click',simulate);root.querySelector('#tc-reset').addEventListener('click',()=>{sendA.clear();sendB.clear();pickA.clear();pickB.clear();render(false);});root.querySelector('#tl-refresh').addEventListener('click',loadContext);deal();refreshPartners();refreshAssetLists();images();}
async function loadContext(){const run=++generation;const button=root.querySelector('#tl-refresh');if(button)button.disabled=true;try{const next=await window.DCCData.json('/api/league/1389344338340761600/roster-center?view=trade-context',{force:true});if(run!==generation)return;context=next;render();applySharedDeal();maybeStartUpgrades();}catch{if(button){button.disabled=false;button.textContent='Retry projections';}}}
window.DCCTradeCenter={findUpgrades,openTeam(id){if(!team(id))return;stopShopping();a=String(id);if(a===b)b=String(teams.find(t=>String(t.rosterId)!==a).rosterId);sendA.clear();sendB.clear();pickA.clear();pickB.clear();filters={a:{query:'',position:'ALL'},b:{query:'',position:'ALL'}};render(false);location.hash='trade-center';},load(next){teams=next||[];if(teams.length<2)return;a=String(teams.find(t=>t.manager==='shwaf')?.rosterId||teams[0].rosterId);b=String(teams.find(t=>String(t.rosterId)!==a).rosterId);sendA.clear();sendB.clear();pickA.clear();pickB.clear();render();loadContext();loadMarkets();}};
const sourceNames={fantasycalc:'FantasyCalc',statsguy:'Stats Guy Fantasy',dynastyprocess:'DynastyProcess'};
const sourceUrls={fantasycalc:'https://fantasycalc.com/',statsguy:'https://statsguyfantasy.com/',dynastyprocess:'https://dynastyprocess.com/'};
function futureView(){
 if(markets.status==='loading')return '<div class="tl-future"><p class="kicker">DYNASTY OUTLOOK</p><h3>Loading the dynasty markets…</h3></div>';
 const d=dynastyTrade(team(a),team(b),sendA,sendB,context.slots,markets,selectedPicks('a'),selectedPicks('b')),v=marketVerdict(d),favored=v.favored==='a'?team(a):v.favored==='b'?team(b):null;
 const title=v.total===1?'Single-source value estimate':favored?`${favored.manager} is favored`:v.balanced?'A balanced dynasty trade':v.total?'The markets are split':'Not enough market coverage';
 const reason=v.total===1?`Only ${sourceNames[d.sources.find(s=>s.complete)?.source]||'one market'} covers every asset · ${favored?'Favors '+favored.manager:v.balanced?'Within the 10% value band':'Limited evidence'}`:favored?`${v.support} of ${v.total} markets favor ${favored.manager}${v.split?' · Sources disagree':''}`:v.balanced?'All covered markets are within 10%':'Compare each market below';
 const best=[...new Map(d.bestAsset.map(s=>[s.name+'|'+s.receives,{...s,sources:d.bestAsset.filter(x=>x.name===s.name&&x.receives===s.receives).map(x=>sourceNames[x.source])}])).values()];
 const players=[...roster(team(a)),...roster(team(b)),...selectedPicks('a'),...selectedPicks('b')];
 return `<section class="tl-future tl-future--redesigned"><div class="tl-verdict-hero">${favored?logo(favored):'<span class="tl-verdict-symbol">⇄</span>'}<div><p class="kicker">DYNASTY MARKET VERDICT</p><h3>${esc(title)}</h3><p>${esc(reason)}</p></div><span class="tl-verdict-pill">${v.total===1?'LIMITED COVERAGE':v.split?'MIXED SIGNAL':favored?'VALUE EDGE':v.balanced?'BALANCED':'INCOMPLETE'}</span></div><div class="tl-future-sides">${d.sides.map((s,i)=>{const edge=v.favored===(i?'b':'a');return `<article class="${edge?'tl-side-favored':favored?'tl-side-unfavored':''}">${logo(s.team)}<h4>${esc(s.team.team)}</h4><strong>${s.core}</strong><span>${s.market}</span><b class="tl-side-label">${edge?'FAVORED':favored?'OTHER SIDE':'EVEN / MIXED'}</b></article>`;}).join('')}</div><div class="tl-market-cards">${d.sources.map(s=>{const total=(s.totals[0]||0)+(s.totals[1]||0),share=total?Math.round(s.totals[1]/total*100):50,winner=s.vote==='a'?team(a):s.vote==='b'?team(b):null;return `<article class="tl-market-card"><header><a href="${sourceUrls[s.source]}" target="_blank" rel="noopener">${sourceNames[s.source]}</a><small>${s.source==='fantasycalc'?'Retrieved':'As of'} ${esc(String(s.asOf).slice(0,10))}</small></header><div class="tl-market-call ${winner?'has-edge':''}">${winner?`Favors ${esc(winner.manager)}`:s.vote==='balanced'?'Balanced':'Coverage incomplete'}<small>${s.complete?`${Math.round(s.relative*100)}% value gap`:esc(s.missing.join(', '))}</small></div><div class="tl-market-values"><div><small>${esc(team(a).manager)} receives</small><strong>${s.totals[1]==null?'—':Math.round(s.totals[1]).toLocaleString()}</strong></div><div><small>${esc(team(b).manager)} receives</small><strong>${s.totals[0]==null?'—':Math.round(s.totals[0]).toLocaleString()}</strong></div></div>${s.complete?`<div class="tl-market-share" aria-hidden="true"><span style="width:${share}%"></span><span style="width:${100-share}%"></span></div>`:''}<div class="tl-core-changes">${s.core.map((n,i)=>`<span>${esc(i?team(b).manager:team(a).manager)} core <b class="${n>0?'is-positive':n<0?'is-negative':''}">${n==null?'—':(n>0?'+':'')+Math.round(n).toLocaleString()}</b></span>`).join('')}</div></article>`;}).join('')||'<p class="notice">Market values are unavailable. Weekly analysis remains separate.</p>'}</div>${best.length?`<div class="tl-best-assets">${best.map(s=>{const player=players.find(p=>p.name===s.name);return `<article>${player?.position==='PICK'?`<span class="tl-pick-icon">${player.round}</span>`:player?photo(player):''}<div><p class="kicker">BEST ASSET</p><strong>${esc(s.name)}</strong><span>Goes to ${esc(s.receives)}</span><small>${esc(s.sources.join(' · '))}</small></div></article>`;}).join('')}</div>`:''}${d.consolidation?'<p class="tl-future-note">Consolidation deal · Compare the best asset and starting core.</p>':''}<details class="tl-depth"><summary>Sources & methodology</summary><p>Values are source estimates, not acceptance probabilities. Player-only suggestions require at least two complete markets; pick packages may have a single-source estimate. All generated offers require a maximum 10% relative value gap in every covered market. Strong fits have supported benefits for both teams. Market-matched options remain available with starting-core, strategy and roster-space tradeoffs disclosed; they are not automatic improvements. Contend requires at least 2 projected weekly points or 2% of the current weekly lineup, whichever is larger; this is a DCC suggestion filter, not a validated acceptance model. Rebuild requires picks to supply at least half the incoming market value and cover the dynasty starting-core loss; a small throw-in pick does not qualify. Balanced preserves dynasty starting-core value. Uneven packages are not given an invented star premium; roster-space and lineup-hole checks apply. Manual analysis still shows any deal. The verdict counts each covered market equally. Sources keep their own value scales; they are not averaged. Within 10% is DCC’s balanced band. Bars compare received market value, not victory odds. Core change uses league slots and includes players on bye or temporarily unavailable. FantasyCalc is requested for the league’s team count, PPR and QB format; other sources are broader format baselines. Dated sources older than 14 days are excluded. Market value is not a future points forecast.</p>${markets.failures?.length?`<p>Unavailable sources: ${esc(markets.failures.map(s=>s.source).join(', '))}</p>`:''}</details></section>`;
}
async function loadMarkets(){try{markets=await window.DCCData.json('/api/league/1389344338340761600/roster-center?view=dynasty-context',{force:true});}catch{markets={status:'unavailable',sources:[]};}refreshAssetLists();renderPlanning();if(root.querySelector('#tc-output')?.textContent)simulate();applySharedDeal();maybeStartUpgrades();}
function refreshAssetLists(){for(const side of ['a','b']){const list=root.querySelector(`#tl-list-${side}`);if(!list)continue;list.innerHTML=pickers(side);bindPicks(side);}images();}
async function generateOffers(){stopShopping();const button=root.querySelector('#tl-build-offer'),output=root.querySelector('#tl-offers'),targets=[...roster(team(b)).filter(p=>sendB.has(pid(p))),...selectedPicks('b')];if(!targets.length){output.innerHTML='<p class="notice">Select the player or package you want from the trade partner’s list.</p>';return;}if(markets.status!=='ready'||!context.slots.length){output.innerHTML='<p class="notice">Market and lineup data are still loading. Try again when ready.</p>';return;}button.disabled=true;button.textContent='Building offers…';await new Promise(resolve=>setTimeout(resolve,0));try{const result=buildOffers({a:team(a),b:team(b),targets,markets,slots:context.slots,context,protectedIds:protectedAssets,goalA:plan(a),goalB:plan(b),teams,needs:rosterNeeds(team(b),teams,markets)});builtOffers=result.offers;if(!builtOffers.length){output.innerHTML=`<p class="notice">${result.status==='missing-market'?'The target package has incomplete market values.':`No sensible package found with your available assets. Try fewer targets or unprotect an asset.`}</p>`;return;}output.innerHTML=`<div class="tl-offer-heading"><p class="kicker">OFFERS FOR ${esc(team(b).manager)}</p><h3>${builtOffers.length} ways to start the conversation</h3></div><div class="tl-offer-grid">${builtOffers.map((o,i)=>{return compactOfferCard(o,{give:o.assets,get:targets,ownSide:0,partner:team(b),open:'data-use-offer',compare:'data-compare-offer',index:i});}).join('')}</div>`;output.querySelectorAll('[data-use-offer]').forEach(btn=>btn.addEventListener('click',()=>{const o=builtOffers[Number(btn.dataset.useOffer)];sendA=new Set(o.assets.filter(p=>p.position!=='PICK').map(pid));pickA=new Set(o.assets.filter(p=>p.position==='PICK').map(pid));o.assets.filter(p=>p.position==='PICK').forEach(p=>pickScenarios.set(p.id,p.scenario));render(false);simulate();root.querySelector('#tl-deal').scrollIntoView({behavior:'smooth',block:'center'});}));images();}catch{output.innerHTML='<p class="notice">Offers could not be built. Try a smaller target package.</p>';}finally{button.disabled=false;button.textContent='Build offers';}}
function renderPlanning(){renderComparison();const needsRoot=root.querySelector('#tl-needs');if(needsRoot){const needs=rosterNeeds(team(b),teams,markets);needsRoot.innerHTML=needs.length?`<div class="tl-needs-line"><span>${esc(team(b).manager)}’s weaker positions</span>${needs.map(n=>`<b class="position-label" data-position="${n.position}">${n.position} · ${n.rank}/${teams.length}</b>`).join('')}<small>Dynasty market depth · Relative to this league</small></div>`:'';}renderSaved();}
function persistSaved(){try{localStorage.setItem('dcc-saved-trades',JSON.stringify(savedDeals));return true;}catch{return false;}}
function saveDeal(){const row={id:String(Date.now()),a,b,sendA:[...sendA],sendB:[...sendB],pickA:[...pickA],pickB:[...pickB],scenarios:Object.fromEntries(pickScenarios),label:`${team(a).manager} ↔ ${team(b).manager}`,created:new Date().toISOString()};if(!row.sendA.length&&!row.sendB.length&&!row.pickA.length&&!row.pickB.length)return;savedDeals=[row,...savedDeals].slice(0,12);const success=persistSaved();renderSaved();root.querySelector('#tl-save-deal').textContent=success?'Saved on this device':'Storage unavailable';}
function renderSaved(){const el=root.querySelector('#tl-saved');if(!el)return;el.innerHTML=savedDeals.length?`<details class="tl-saved-deals"><summary>Saved deals · ${savedDeals.length}</summary>${savedDeals.map(s=>`<article><div><strong>${esc(s.label)}</strong><small>${esc(s.created.slice(0,10))} · ${s.sendA.length+s.pickA.length} ↔ ${s.sendB.length+s.pickB.length} assets</small></div><button class="button button--ghost" data-load-deal="${s.id}">Open</button><button class="tl-remove" data-remove-deal="${s.id}" aria-label="Remove saved deal">×</button></article>`).join('')}<small>Saved on this device. Values refresh when reopened.</small></details>`:'';el.querySelectorAll('[data-load-deal]').forEach(button=>button.addEventListener('click',()=>{const s=savedDeals.find(x=>x.id===button.dataset.loadDeal);if(!validateSavedDeal(s,teams,markets.picks||[])){button.textContent='Ownership changed';return;}a=s.a;b=s.b;sendA=new Set(s.sendA);sendB=new Set(s.sendB);pickA=new Set(s.pickA);pickB=new Set(s.pickB);pickScenarios=new Map(Object.entries(s.scenarios||{}));render(false);simulate();}));el.querySelectorAll('[data-remove-deal]').forEach(button=>button.addEventListener('click',()=>{savedDeals=savedDeals.filter(s=>s.id!==button.dataset.removeDeal);persistSaved();renderSaved();}));}
function findCounter(){const assetsA=[...roster(team(a)).filter(p=>sendA.has(pid(p))),...selectedPicks('a')],assetsB=[...roster(team(b)).filter(p=>sendB.has(pid(p))),...selectedPicks('b')],options=counterAdjustments({a:team(a),b:team(b),assetsA,assetsB,markets,protectedIds:protectedAssets}),el=root.querySelector('#tl-counter-options');el.innerHTML=options.length?`<div class="tl-counters">${options.map((c,i)=>`<article><div><strong>${esc(c.side?team(b).manager:team(a).manager)} adds ${esc(c.asset.name)}</strong><small>Market gap ${Math.round(c.before*100)}% → ${Math.round(c.after*100)}% · ${c.sources} covered markets</small></div><button class="button button--ghost" data-counter="${i}">Try adjustment</button></article>`).join('')}</div>`:'<p class="notice">No single-asset adjustment improves the gap within the covered markets. The deal may already be balanced, or need a different package.</p>';el.querySelectorAll('[data-counter]').forEach(button=>button.addEventListener('click',()=>{const c=options[Number(button.dataset.counter)],set=c.asset.position==='PICK'?(c.side?pickB:pickA):(c.side?sendB:sendA);set.add(pid(c.asset));if(c.asset.position==='PICK')pickScenarios.set(c.asset.id,c.asset.scenario);render(false);simulate();}));}
function stopShopping(){if(upgradeWorker){upgradeWorker.terminate();upgradeWorker=null;const output=root.querySelector("#tl-upgrades");if(output)output.innerHTML='<p class="notice">Upgrade search stopped.</p>';}if(shopWorker){shopWorker.terminate();shopWorker=null;}const button=root.querySelector('#tl-shop');if(button){button.disabled=false;button.textContent='Shop my players';}}
function shopPlayers(){stopShopping();const output=root.querySelector('#tl-offers'),targets=[...roster(team(a)).filter(p=>sendA.has(pid(p))),...selectedPicks('a')];if(!targets.length){output.innerHTML='<p class="notice">Select a player or package from your own roster first.</p>';return;}if(targets.some(p=>protectedAssets.has(pid(p)))){output.innerHTML='<p class="notice">Unprotect the selected assets before shopping them.</p>';return;}if(markets.status!=='ready'||!context.slots.length){output.innerHTML='<p class="notice">Market and lineup data are still loading. Try again when ready.</p>';return;}const button=root.querySelector('#tl-shop');button.disabled=true;button.textContent='Searching the league…';output.innerHTML='<p class="notice">Searching the other rosters · 0 / 9</p>';try{shopWorker=new Worker(new URL('./trade-shop-worker.js',import.meta.url),{type:'module'});shopWorker.onmessage=event=>{const d=event.data;if(d.type==='progress'){output.innerHTML=`<p class="notice">Searching the other rosters · ${d.done} / ${d.total}</p>`;}else if(d.type==='complete'){shopResults=d.offers;stopShopping();renderShop();}else{stopShopping();output.innerHTML='<p class="notice">Search could not finish. Try a smaller package.</p>';}};shopWorker.onerror=()=>{stopShopping();output.innerHTML='<p class="notice">Search could not finish. Try again.</p>';};shopWorker.postMessage({own:team(a),teams,targets,markets,slots:context.slots,context,plans,protectedIds:[...protectedAssets]});}catch{stopShopping();output.innerHTML='<p class="notice">The league search is unavailable in this browser.</p>';}}
function renderShop(){const output=root.querySelector('#tl-offers');if(!shopResults.length){output.innerHTML=shoppingDirection()+`<p class="notice">${plan(a)==='Balanced'?'No market-matched returns were found with the available values and protected assets.':"No supported returns meet the selected strategies and current value checks. Try Balanced to explore other tradeoffs."}</p>`;return;}output.innerHTML=`<div class="tl-offer-heading"><p class="kicker">THE MARKET FOR YOUR PACKAGE</p><h3>${shopResults.length} possible returns from the league</h3>${shoppingDirection()}</div><div class="tl-offer-grid">${shopResults.map((o,i)=>{return compactOfferCard(o,{give:o.send,get:o.receive,ownSide:1,partner:o.other,open:'data-shop-offer',compare:'data-compare-shop',index:i,type:'tl-shop-card'});}).join('')}</div>`;output.querySelectorAll('[data-shop-offer]').forEach(button=>button.addEventListener('click',()=>{const o=shopResults[Number(button.dataset.shopOffer)];b=String(o.other.rosterId);sendA=new Set(o.send.filter(p=>p.position!=='PICK').map(pid));pickA=new Set(o.send.filter(p=>p.position==='PICK').map(pid));sendB=new Set(o.receive.filter(p=>p.position!=='PICK').map(pid));pickB=new Set(o.receive.filter(p=>p.position==='PICK').map(pid));[...o.send,...o.receive].filter(p=>p.position==='PICK').forEach(p=>pickScenarios.set(p.id,p.scenario||'generic'));filters={a:{query:'',position:'ALL'},b:{query:'',position:'ALL'}};render(false);simulate();root.querySelector('#tl-deal').scrollIntoView({behavior:'smooth',block:'center'});}));images();}
function currentDeal(){return cleanDeal({a,b,sendA:[...sendA],sendB:[...sendB],pickA:[...pickA],pickB:[...pickB],scenarios:Object.fromEntries(pickScenarios)});}
function packageDeal(own,other,give,get){return cleanDeal({a:String(own.rosterId),b:String(other.rosterId),sendA:give.filter(p=>p.position!=='PICK').map(pid),sendB:get.filter(p=>p.position!=='PICK').map(pid),pickA:give.filter(p=>p.position==='PICK').map(pid),pickB:get.filter(p=>p.position==='PICK').map(pid),scenarios:Object.fromEntries([...give,...get].filter(p=>p.position==='PICK').map(p=>[p.id,p.scenario||'generic']))});}
function assetsFor(d,side){const t=team(side==='a'?d.a:d.b),players=side==='a'?d.sendA:d.sendB,picks=side==='a'?d.pickA:d.pickB;return [...roster(t).filter(p=>players.includes(pid(p))),...(markets.picks||[]).filter(p=>picks.includes(p.id)).map(p=>({...p,scenario:d.scenarios[p.id]||'generic'}))];}
function analyzeSnapshot(d){if(!validateSavedDeal(d,teams,markets.picks||[]))return null;const aa=assetsFor(d,'a'),bb=assetsFor(d,'b');return {aa,bb,dynasty:dynastyTrade(team(d.a),team(d.b),d.sendA,d.sendB,context.slots,markets,aa.filter(p=>p.position==='PICK'),bb.filter(p=>p.position==='PICK')),weekly:evaluateTrade(team(d.a),team(d.b),d.sendA,d.sendB,context.slots,context)};}
function addComparison(d,button){try{const result=shortlistDeal(compareDeals,d);compareDeals=result.rows;compareOpen=true;try{localStorage.setItem('dcc-compare-deals',JSON.stringify(compareDeals));}catch{}renderComparison();button.textContent=result.status==='full'?'Shortlist full (3)':result.status==='already-added'?'Already shortlisted':'Added to comparison';}catch{button.textContent='Select assets first';}}
function openSnapshot(d){if(!validateSavedDeal(d,teams,markets.picks||[]))return false;a=d.a;b=d.b;sendA=new Set(d.sendA);sendB=new Set(d.sendB);pickA=new Set(d.pickA);pickB=new Set(d.pickB);pickScenarios=new Map(Object.entries(d.scenarios));render(false);simulate();return true;}
function renderComparison(){const el=root.querySelector('#tl-compare');if(!el)return;el.innerHTML=compareDeals.length?`<details class="tl-comparison" ${compareOpen?'open':''}><summary>Compare offers · ${compareDeals.length} / 3</summary><div class="tl-comparison-grid">${compareDeals.map((d,i)=>{const analysis=context.slots.length&&markets.status!=='loading'?analyzeSnapshot(d):null;return `<article><header><strong>Offer ${i+1} · ${esc(team(d.b)?.manager||'Unknown team')}</strong><button class="tl-remove" data-remove-compare="${i}" aria-label="Remove offer ${i+1} from comparison">×</button></header>${analysis?`<small>${esc(team(d.a).manager)} SENDS</small>${analysis.aa.map(asset).join('')}<small>${esc(team(d.a).manager)} RECEIVES</small>${analysis.bb.map(asset).join('')}<div class="tl-compare-impact"><strong>${analysis.dynasty.sides[0].core}</strong><span>${analysis.dynasty.sides[0].market} · ${analysis.dynasty.usable} covered markets</span><span>Weekly change <b class="${analysis.weekly[0].delta<0?'is-negative':analysis.weekly[0].delta>0?'is-positive':''}">${signed(analysis.weekly[0].delta)} pts</b></span><span>Partner core: ${analysis.dynasty.sides[1].core}</span><span>Picks sent / received: ${d.pickA.length} / ${d.pickB.length}</span></div><button class="button button--ghost" data-open-compare="${i}">Open full analysis</button>`:`<p class="notice">${markets.status==='loading'?'Loading current values…':'Ownership changed. This offer needs updating.'}</p>`}</article>`;}).join('')}</div><small>Recalculated with current data · Saved on this device</small></details>`:'';el.querySelector('details')?.addEventListener('toggle',e=>compareOpen=e.currentTarget.open);el.querySelectorAll('[data-remove-compare]').forEach(button=>button.addEventListener('click',()=>{compareDeals.splice(Number(button.dataset.removeCompare),1);try{localStorage.setItem('dcc-compare-deals',JSON.stringify(compareDeals));}catch{}renderComparison();}));el.querySelectorAll('[data-open-compare]').forEach(button=>button.addEventListener('click',()=>openSnapshot(compareDeals[Number(button.dataset.openCompare)])));images();}
async function copyCurrent(kind){const output=root.querySelector('#tl-share-output');try{const d=currentDeal(),link=shareUrl(d,location.origin),analysis=analyzeSnapshot(d);if(!analysis)throw Error('Ownership has changed. Update this deal before sharing.');const text=kind==='link'?link:offerMessage({a:team(a),b:team(b),assetsA:analysis.aa,assetsB:analysis.bb,dynasty:analysis.dynasty,weekly:analysis.weekly,link});output.innerHTML=`<label class="tl-share-box">${kind==='link'?'Share this trade':'Offer message'}<textarea readonly aria-label="${kind==='link'?'Trade share link':'Trade offer message'}"></textarea></label><p class="tl-copy-status"></p>`;output.querySelector('textarea').value=text;try{await navigator.clipboard.writeText(text);output.querySelector('.tl-copy-status').textContent='Copied.';}catch{output.querySelector('.tl-copy-status').textContent='Select the text above to copy.';}}catch(e){output.textContent=e.message;}}
function applySharedDeal(){if(sharedHandled||!context.slots.length||markets.status==='loading')return;const token=new URLSearchParams(location.search).get('deal');sharedHandled=true;if(!token)return;try{const d=decodeDeal(token);if(!openSnapshot(d))throw Error('An asset in this shared deal has changed owners or is no longer available. Update the package before analyzing.');shareNotice='Shared deal loaded · Values recalculated now';}catch(e){shareNotice=e.message;}const notice=root.querySelector('#tl-share-notice');if(notice){notice.textContent=shareNotice;notice.hidden=false;}}
root?.addEventListener('click',e=>{const offer=e.target.closest('[data-compare-offer]'),shop=e.target.closest('[data-compare-shop]');if(offer){const o=builtOffers[Number(offer.dataset.compareOffer)],get=[...roster(team(b)).filter(p=>sendB.has(pid(p))),...selectedPicks('b')];if(o)addComparison(packageDeal(team(a),team(b),o.assets,get),offer);}if(shop){const o=shopResults[Number(shop.dataset.compareShop)];if(o)addComparison(packageDeal(team(a),o.other,o.send,o.receive),shop);}});

function findUpgrades(rosterId,position,assumption="Existing"){upgradeAssumption=assumption;if(!['QB','RB','WR','TE'].includes(position)||!team(rosterId))return;stopShopping();a=String(rosterId);b=String(teams.find(t=>String(t.rosterId)!==a).rosterId);sendA.clear();sendB.clear();pickA.clear();pickB.clear();filters={a:{query:'',position:'ALL'},b:{query:'',position}};render(false);upgradeIntent={rosterId:a,position};location.hash='trade-center';maybeStartUpgrades();root.querySelector('#tl-upgrades').scrollIntoView({behavior:'smooth',block:'start'});}
function maybeStartUpgrades(){if(!upgradeIntent)return;const output=root.querySelector('#tl-upgrades');if(!output)return;if(markets.status==='loading'||!context.slots.length){output.innerHTML='<p class="notice" role="status">Loading current values for your upgrade search…</p>';return;}const intent=upgradeIntent;upgradeIntent=null;if(markets.status!=='ready'){output.innerHTML='<p class="notice">Market data is unavailable. Refresh data and try the upgrade search again.</p>';return;}if(a!==intent.rosterId)return;upgradePosition=intent.position;output.innerHTML=`<div class="tl-upgrade-heading"><p class="kicker">A PLAN FOR YOUR ROSTER</p><h3>Finding ${upgradePosition} upgrades for ${esc(team(a).manager)}</h3>${upgradeControls()}<p role="status">Searching 0 of ${teams.length-1} teams…</p><button class="button button--ghost" data-cancel-upgrades>Cancel search</button></div>`;output.querySelector('[data-cancel-upgrades]').onclick=stopShopping;
 try{const worker=new Worker(new URL('./position-upgrades-worker.js',import.meta.url),{type:'module'});upgradeWorker=worker;worker.onmessage=event=>{if(upgradeWorker!==worker)return;const d=event.data;if(d.type==='progress')output.querySelector('[role="status"]').textContent=`Searching ${d.done} of ${d.total} teams…`;else{worker.terminate();upgradeWorker=null;if(d.type==='complete'){upgradeResults=d.offers;renderUpgrades();}else output.innerHTML='<p class="notice">Upgrade search could not finish. Try again from Roster Outlook.</p>';}};worker.onerror=()=>{if(upgradeWorker!==worker)return;worker.terminate();upgradeWorker=null;output.innerHTML='<p class="notice">Upgrade search is unavailable. Try again from Roster Outlook.</p>';};worker.postMessage({own:team(a),teams,position:upgradePosition,markets,slots:context.slots,context,plans:upgradeAssumption==='Existing'?plans:Object.fromEntries(teams.map(t=>[String(t.rosterId),String(t.rosterId)===a?plan(a):upgradeAssumption])),protectedIds:[...protectedAssets]});}catch{output.innerHTML='<p class="notice">Upgrade search is unavailable in this browser.</p>';}}
function renderUpgrades(){const output=root.querySelector('#tl-upgrades');output.innerHTML=`<div class="tl-upgrade-heading"><p class="kicker">A PLAN FOR YOUR ROSTER</p><h3>${upgradePosition} upgrades for ${esc(team(a).manager)}</h3>${upgradeControls()}<p>${upgradeResults.length?'Packages that improve your position group and dynasty starting core.':'No supported two-sided upgrades fit the selected strategies and current values.'}</p></div>${upgradeResults.length?`<div class="tl-offer-grid">${upgradeResults.map((o,i)=>{return compactOfferCard(o,{give:o.send,get:o.receive,ownSide:0,partner:o.other,open:'data-open-upgrade',compare:'data-compare-upgrade',index:i,type:'tl-upgrade-card'});}).join('')}</div>`:'<p class="notice">Build a custom deal below, or select a partner’s Contend / Rebuild strategy to explore a different tradeoff. Strategy choices are assumptions, not that manager’s stated preference.</p>'}`;output.querySelectorAll('[data-open-upgrade]').forEach(button=>button.onclick=()=>{const o=upgradeResults[Number(button.dataset.openUpgrade)];openSnapshot(packageDeal(team(a),o.other,o.send,o.receive));root.querySelector('#tc-output').scrollIntoView({behavior:'smooth',block:'start'});});output.querySelectorAll('[data-compare-upgrade]').forEach(button=>button.onclick=()=>{const o=upgradeResults[Number(button.dataset.compareUpgrade)];addComparison(packageDeal(team(a),o.other,o.send,o.receive),button);});images();}

root?.addEventListener('change',e=>{if(e.target.matches('#tc-a,#tc-b,[data-side],[data-kind="pick"],[data-plan],[data-pick]'))upgradeIntent=null;});

function upgradeControls(){return `<div class="tl-upgrade-strategies" aria-label="Partner strategy scenarios"><span>Partner scenario</span>${[['Existing','Selected strategies'],['Contend','Contending partner'],['Rebuild','Rebuilding partner']].map(([value,label])=>`<button type="button" class="button button--ghost" data-upgrade-strategy="${value}" aria-pressed="${upgradeAssumption===value}">${label}</button>`).join('')}<small>${upgradeAssumption==='Existing'?'Uses your selected team strategies.':'Contend tests this week’s lineup; Rebuild tests draft capital. These are scenarios, not stated manager preferences.'}</small></div>`;}
root?.addEventListener('click',e=>{const button=e.target.closest('[data-upgrade-strategy]');if(button)findUpgrades(a,upgradePosition,button.dataset.upgradeStrategy);});

function compactAsset(p){if(p.position==='PICK')return `<div class="offer-mini-asset"><span class="offer-pick-mark">${esc(p.round)}<small>PICK</small></span><span><strong>${esc(p.season)} · Round ${esc(p.round)}</strong><small>${esc(p.originalManager||p.name)}${p.scenario&&p.scenario!=='generic'?' · '+esc(p.scenario):''}</small></span></div>`;return `<div class="offer-mini-asset">${photo(p)}<span><strong>${esc(p.name)}</strong><small>${pos(p)} · ${esc(p.nflTeam||'FA')}</small></span></div>`;}
function compactOfferCard(o,{give,get,ownSide,partner,open,compare,index,type=''}){
 const q=o.quality,own=o.dynasty.sides[ownSide],other=o.dynasty.sides[1-ownSide],weekly=o.weekly[ownSide].delta,partnerWeekly=o.weekly[1-ownSide].delta,core=own.core,coreUp=core==='Stronger dynasty core',coreDown=core==='Dynasty core weakened',coreLabel=coreUp?'Core improves':coreDown?'Core decreases':core==='Core largely preserved'?'Core preserved':'Core uncertain',strong=q.tier==='strong-fit',drops=q.sides.map((side,i)=>side.drops?`${i===ownSide?'You':'Partner'}: free ${side.drops} ${side.drops===1?'spot':'spots'}`:'').filter(Boolean),ratios=o.dynasty.sources.filter(s=>s.complete&&s.totals[ownSide]>0).map(s=>s.totals[1-ownSide]/s.totals[ownSide]),low=Math.round(Math.min(...ratios)*100),high=Math.round(Math.max(...ratios)*100);
 return `<article class="tl-offer-card offer-compact ${type}"><header>${logo(partner)}<div class="offer-partner"><h4>${esc(partner.manager)}</h4><small>${esc(partner.team)}</small></div><span class="offer-fit-tag ${strong?'is-strong':''}">${strong?'Strong fit':'Tradeoff'}</span></header><div class="offer-exchange"><section><h5>You receive</h5>${get.map(compactAsset).join('')}</section><section><h5>You send</h5>${give.map(compactAsset).join('')}</section></div><div class="offer-snapshot"><span class="offer-impact ${weekly<0?'is-negative':weekly>0?'is-positive':''}"><b>${signed(weekly)}<small> pts</small></b><small>This week</small></span><span class="offer-core ${coreUp?'is-positive':coreDown?'is-negative':''}"><b>${coreUp?'↗':coreDown?'↘':'—'} ${coreLabel}</b><small>${esc(o.rosterFit?.sides[ownSide]?.label||'Dynasty')}</small></span><span class="offer-coverage ${q.sourceCount===1?'is-limited':''}"><b>${q.sourceCount===1?'Single source':q.sourceCount+' sources'}</b><small>${q.sourceCount===1?'Limited coverage':'Value matched'}</small></span></div>${drops.length?`<p class="offer-drop-note">${esc(drops.join(' · '))}</p>`:''}<details class="offer-details"><summary>Trade details</summary><div><p><b>You:</b> ${o.rosterFit?esc(o.rosterFit.sides[ownSide].text)+' ':''}${esc(q.sides[ownSide].text)}.</p><p><b>${esc(partner.manager)}:</b> ${o.rosterFit?esc(o.rosterFit.sides[1-ownSide].text)+' ':''}${esc(q.sides[1-ownSide].text)}.</p><p>Partner weekly change <strong class="${partnerWeekly<0?'is-negative':partnerWeekly>0?'is-positive':''}">${signed(partnerWeekly)} pts</strong> · ${esc(other.core)}.</p><p>${esc(q.coverage)} · Return value ${low===high?low:low+'–'+high}% of the outgoing package.</p>${drops.length?'<p class="offer-drop-warning">A roster move is required. Drop cost is not included in these values.</p>':''}</div></details><footer><button class="button button--primary" ${open}="${index}">Open trade <span aria-hidden="true">→</span></button><button class="button button--ghost" ${compare}="${index}" aria-label="Compare offer ${index+1} with ${esc(partner.manager)}">Compare</button></footer></article>`;
}

function shoppingDirection(){return `<div class="tl-shop-direction" aria-label="Shopping direction">${[['Balanced','Balanced'],['Contend','Win now'],['Rebuild','Future value']].map(([value,label])=>`<button type="button" class="button button--ghost" data-shop-direction="${value}" aria-pressed="${plan(a)===value}" title="${value==='Contend'?"Prioritize this week's projected lineup":value==='Rebuild'?'Prioritize valued future draft capital':'Balance starter fit, replacement and draft capital'}">${label}</button>`).join('')}</div>`;}
root?.addEventListener('click',e=>{const button=e.target.closest('[data-shop-direction]');if(!button)return;plans[a]=button.dataset.shopDirection;try{localStorage.setItem('dcc-trade-plans',JSON.stringify(plans));}catch{}const select=root.querySelector(`[data-plan="${a}"]`);if(select)select.value=plan(a);shopPlayers();});
